{
  "shortname": "biobricks-pubchem-annotations",
  "title": "BioBricks PubChem Annotations",
  "description": "BioBricks PubChem Annotations is an open knowledge graph of chemical annotations from PubChem.",
  "homepage": "https://github.com/biobricks-ai/pubchem-annotations-kg",
  "named_graph": "https://purl.org/okn/frink/kg/biobricks-pubchem-annotations",
  "payload": [
    "chemical"
  ]
}

{
  "shortname": "identifier-mappings",
  "title": "ID Mappings",
  "description": "Mappings using standard RDF predicates between Wikidata entities and external identifiers represented as RDF IRIs",
  "homepage": "https://www.wikidata.org/",
  "named_graph": "https://purl.org/okn/frink/kg/identifier-mappings",
  "payload": [
    "identifier_mapping"
  ]
}

{
  "shortname": "okn-void",
  "title": "OKN VoID graph descriptions",
